          "label": "Quantity",
          "placeholder": "1",
          "required": true,
          "min": 1
        },
        {
          "type": "number",
          "name": "price",
          "label": "Price ($)",
          "placeholder": "29.99",
          "required": true,
          "min": 0
        },
        {
          "type": "select",
          "name": "currency",
          "label": "Currency",
          "required": true,
          "options": [
            {
              "label": "USD",
              "value": "USD"
            },
            {
              "label": "EUR",
              "value": "EUR"
            },
            {
              "label": "GBP",
              "value": "GBP"
            }
          ]
        },
        {
          "type": "empty",
          "name": "spacerDisplay",
          "excludeFromSubmit": true
        },
        {
          "type": "preview",
          "name": "lineTotal",
          "label": "Estimated Total",
          "excludeFromSubmit": true,
          "watchFields": [
            "qty",
            "price"
