          "calculation": {
            "rule": "multiply"
          },
          "decimals": 2,
          "variant": "highlight"
        },
        {
          "type": "preview",
          "name": "orderLabel",
          "label": "Order Label",
          "excludeFromSubmit": true,
          "watchFields": [
